*   **`data-sort` Attribute:**  This is the key.  We add a `data-sort` attribute to each `<th>` (table header).  The value of this attribute tells our JavaScript what type of sorting to apply.  Common values are:
    *   `string`: For alphabetical sorting (both ascending and descending).
    *   `number`: For numerical sorting.
    *   `date`: For date sorting (assuming dates are in a consistent format like YYYY-MM-DD).  You might need to adjust the date parsing if your format is different.

**2. CSS (Optional, for visual indication of sorting)**

```css
.sorted-asc {
  font-weight: bold;
  color: green; /* Or any other visual cue */
}

.sorted-desc {
  font-weight: bold;
  color: red; /* Or any other visual cue */
}
```

This CSS provides a simple visual indication (bold text and different colors) to show which column is currently sorted and in what direction (ascending or descending).

**3. JavaScript (Sorting Logic)**

```javascript
const table = document.querySelector('.table');

table.addEventListener('click', (event) => {
  if (event.target.tagName === 'TH') {
    const header = event.target;
    const sortType = header.dataset.sort;
    const columnIndex = header.cellIndex;

    // Get the table body
    const tbody = table.querySelector('tbody');
    const rows = Array.from(tbody.querySelectorAll('tr'));

    // Sort the rows
    rows.sort((rowA, rowB) => {
      const cellA = rowA.querySelectorAll('td')[columnIndex].textContent;
      const cellB = rowB.querySelectorAll('td')[columnIndex].textContent;

      let comparison = 0;

      switch (sortType) {
        case 'string':
          comparison = cellA.localeCompare(cellB);
          break;
        case 'number':
          comparison = parseFloat(cellA) - parseFloat(cellB);
          break;
        case 'date':
          comparison = new Date(cellA) - new Date(cellB);
          break;
        default:
          comparison = cellA.localeCompare(cellB); // Default to string
      }

      return comparison;
    });

    // Remove existing sort classes
    table.querySelectorAll('th').forEach(th => {
      th.classList.remove('sorted-asc', 'sorted-desc');
    });

    // Add new sort class
    if (header.classList.contains('sorted-asc')) {
      header.classList.remove('sorted-asc');
      header.classList.add('sorted-desc');
    } else {
      header.classList.add('sorted-asc');
    }

    // Rebuild the table body
    tbody.innerHTML = '';
    rows.forEach(row => tbody.appendChild(row));
  }
});
