/**
 * Packs an array of entities into an ArrayBuffer.
 *
 * @param {Array<Object>} entities An array of entities, where each entity has 'id' (4 bits) and 'size' (3 bits) properties.
 * @returns {ArrayBuffer} An ArrayBuffer containing the packed entities.
 * @throws {Error} If an entity's id or size is out of range.
 */
function packEntities(entities) {
  const totalBits = entities.length * 7; // 4 bits (id) + 3 bits (size) = 7 bits per entity
  const buffer = new ArrayBuffer(Math.ceil(totalBits / 8));
  const view = new DataView(buffer);
  let bitOffset = 0;

  for (const entity of entities) {
    const id = entity.id;
    const size = entity.size;

    if (id < 0 || id > 15) {
      throw new Error("Entity ID must be between 0 and 15.");
    }
    if (size < 0 || size > 7) {
      throw new Error("Entity Size must be between 0 and 7.");
    }

    // Pack ID (4 bits)
    view.setUint8(Math.floor(bitOffset / 8), (view.getUint8(Math.floor(bitOffset / 8)) & 0x0F) | (id << 4));
    bitOffset += 4;

    // Pack Size (3 bits)
    view.setUint8(Math.floor(bitOffset / 8), (view.getUint8(Math.floor(bitOffset / 8)) & 0x07) | (size << 3));
    bitOffset += 3;
  }

  return buffer;
}

/**
 * Unpacks an array of entities from an ArrayBuffer.
 *
 * @param {ArrayBuffer} buffer The ArrayBuffer containing the packed entities.
 * @returns {Array<Object>} An array of entities unpacked from the ArrayBuffer.
 */
function unpackEntities(buffer) {
  const view = new DataView(buffer);
  const entities = [];
  let bitOffset = 0;

  while (bitOffset < buffer.byteLength * 8) {
    const byte = view.getUint8(Math.floor(bitOffset / 8));
    const id = (byte & 0x0F) >> 4;
    const size = (byte & 0x07) >> 3;

    entities.push({ id, size });
    bitOffset += 7;
  }

  return entities;
}
```

